<template><view class="business-page feature-page" :class="{'wholesale-dashboard':context?.module==='wholesale'}"><image class="business-background" src="/static/partner/bg-overview.png" mode="scaleToFill"/><view class="business-header"><text>{{moduleInfo?.title||'联营中心'}}</text></view><FeaturePageState :status="status" :error="error" @retry="load"/><template v-if="status==='ready'&&overview"><view class="business-identity"><view class="business-person"><view v-if="context.module==='wholesale'" class="business-avatar">{{overview.name?.slice(0,1)}}</view><view><view class="business-name">{{context.module==='wholesale'?overview.name:context.label}}</view><text class="business-muted">{{context.module==='wholesale'?`ID：${overview.accountId}`:context.scopeLabel||`共${moduleContexts.length}家门店`}}</text><button v-if="context.module==='wholesale'&&overview.inviteCode" class="business-text-button business-invite" @click="copyInvite"><text>邀请码：{{overview.inviteCode}}</text><image src="/static/common/icon-copy.png" mode="aspectFit"/></button><button v-if="context.module==='agency'" class="business-text-button" @click="contextOpen=true">切换身份</button></view></view><button class="business-switch" @click="moduleOpen=true"><image src="/static/common/icon-switch.png" mode="aspectFit"/><text>切换模块</text></button></view><view v-if="context.module==='wholesale'" class="business-card rank-card"><text class="business-badge">当前等级</text><view class="rank-title">{{overview.levelName}}</view><text class="business-muted">{{overview.rankDescription || '尊享合伙权益'}}</text><template v-if="overview.partnerStatus==='NONE'"><view class="rank-experience"><view :style="{width:`${Math.min(100,(overview.experience || 0)/(overview.experienceTarget || 1)*100)}%`}"/></view><text class="business-muted">{{overview.experience ?? 0}}/{{overview.experienceTarget ?? '—'}}</text></template><view v-else class="rank-footer"><text class="business-muted">{{overview.annualRemainingDays == null ? '' : `权益将在${overview.annualRemainingDays}天后到期`}}</text><view class="rank-links"><button @click="openId('experience')">经验明细</button><button @click="openId('promotion')">晋升任务</button></view></view></view><view v-if="context.module==='costore'" class="business-card business-store"><image src="/static/partner/icon-store-info.png" mode="aspectFit"/><view><view class="business-name">{{context.store?.name||context.label}}</view><text class="business-muted">{{context.store?.number}} {{context.store?.address}}</text><text class="business-muted">{{context.validUntil?`有效期至 ${context.validUntil.slice(0,10)}`:'有效期以后台为准'}}</text><button class="business-text-button" @click="contextOpen=true">切换门店</button></view></view><view v-if="context.module==='agency'" class="business-stats"><button @click="openId('team')"><text>我的团队</text><text class="business-stat-value">{{overview.teamCount ?? '—'}}人</text></button><button @click="openId('income')"><text>代理收益（可提现）</text><text class="business-stat-value">¥{{money(overview.available)}}</text></button></view><view v-if="context.module==='agency'" class="business-relations"><button @click="showRelation('superior')"><text>区域上级</text><view>{{overview.superior?.name||'暂未提供'}}</view></button><button @click="showRelation('referrer')"><text>推荐人</text><view>{{overview.referrer?.name||'暂未提供'}}</view></button></view><view class="business-tool-grid" :class="{compact:context.module!=='wholesale'}"><button v-for="item in (overview.partnerStatus==='NONE'?[]:homeTools)" :key="item.id" @click="openTool(item)"><image :src="item.icon" mode="aspectFit"/><text>{{item.label}}</text></button></view><view v-if="!tools.length" class="business-muted business-empty">当前身份暂无经营功能权限</view><view v-if="context.module==='wholesale' && overview.partnerStatus!=='NONE'" class="business-stats"><button @click="openId('team')"><text>团队人数</text><text class="business-stat-value">{{overview.teamCount ?? '—'}}</text><text>团队明细</text></button><button @click="openId('quota-ledger')"><text>剩余VIP</text><text class="business-stat-value">{{overview.quota ?? '—'}}</text><text>进货明细</text></button><button @click="openId('quota-transfers')"><text>已划拨VIP</text><text class="business-stat-value">{{overview.transferred ?? '—'}}</text><text>划转明细</text></button></view><view class="business-benefits"><view class="business-section-title"><text class="benefits-spark">✦</text> 等级权益 <text class="benefits-spark">✦</text></view><view v-if="overview.benefits.length>1" class="business-benefit-tabs"><button v-for="item in overview.benefits" :key="item.id" :class="{selected:tierId===item.id}" @click="tierId=item.id">{{item.label}}</button></view><ManagedRichContent v-if="benefit" :content="benefit.content"/><EmptyState v-if="context.module==='wholesale' && !benefit?.content?.nodes?.length"/></view></template><view v-if="moduleOpen" class="business-mask" @click.self="moduleOpen=false"><view class="business-dialog"><view class="business-dialog-title">切换模块<button aria-label="关闭模块切换" @click="moduleOpen=false"><image src="/static/common/icon-close.png" mode="aspectFit"/></button></view><view class="business-module-options"><button v-for="item in modules" :key="item.id" @click="switchModule(item.id)"><image :src="item.icon" mode="aspectFit"/><text>{{item.label}}</text><text v-if="context?.module===item.id" class="business-muted">当前模块</text></button></view></view></view><view v-if="contextOpen" class="feature-mask" @click.self="contextOpen=false"><view class="feature-sheet"><view class="panel-heading">{{context.module==='costore'?'切换门店':'切换身份'}}<button class="close-feature" aria-label="关闭身份选择" @click="contextOpen=false"><image src="/static/common/icon-close.png" mode="aspectFit"/></button></view><button v-for="item in moduleContexts" :key="item.id" class="business-context-option" @click="switchContext(item.id)"><view>{{item.label}}</view><text>{{item.scopeLabel||item.store?.address||item.validUntil?.slice(0,10)}}</text><image :src="item.id===context.id?'/static/common/icon-radio-checked.png':'/static/common/icon-radio-unchecked.png'" mode="aspectFit"/></button></view></view><view v-if="relationOpen" class="business-mask business-relation-mask" @click.self="relationOpen=null"><view class="business-relation-dialog"><button class="business-relation-close" aria-label="关闭关系信息" @click="relationOpen=null">×</button><view class="business-relation-title">{{relationTitle}}</view><view class="business-relation-profile"><view class="business-relation-avatar">{{(relation.name||"—").slice(0,1)}}</view><view><view>{{relation.name||"暂未提供"}}</view><text>{{relation.scopeLabel||"信息待后台提供"}}</text></view></view><text class="business-relation-note">关系与授权范围由后台确认</text></view></view><WholesaleReport v-if="wholesaleOverlay" :key="wholesaleOverlay" :tool-id="wholesaleOverlay" :page-query="overlayQuery" overlay @close="wholesaleOverlay=''"/><AppTabBar active="partners"/></view></template>
<script setup>
import {ref,computed,onMounted,onUnmounted} from 'vue'
import {config} from '../config'
import {useAuth} from '../composables/useAuth'
import {useAppTabBar} from '../composables/useAppTabBar'
import {businessModules,businessPreview,businessHomeTools} from '../features/business/catalog'
import {money} from '../features/exclusive/format'
import {getBusinessContexts,getBusinessContext,getBusinessOverview,selectBusinessContext} from '../services/business'
import FeaturePageState from './FeaturePageState.vue'
import ManagedRichContent from './ManagedRichContent.vue'
import AppTabBar from './AppTabBar.vue'
import EmptyState from './EmptyState.vue'
import WholesaleReport from './WholesaleReport.vue'
const props=defineProps({initialModule:{type:String,default:''}})
useAuth();useAppTabBar()
const preview=businessPreview(config),status=ref('loading'),error=ref(''),overview=ref(null),contexts=ref([]),tierId=ref(''),moduleOpen=ref(false),contextOpen=ref(false),relationOpen=ref('')
const wholesaleOverlay=ref(''),overlayQuery=computed(()=>({contextId:context.value?.id}))
let epoch=0,contextId='',switching=false
const homeTools=computed(()=>businessHomeTools(tools.value,context.value))
const context=computed(()=>overview.value?.context),moduleInfo=computed(()=>businessModules.find(item=>item.id===context.value?.module)),modules=computed(()=>businessModules.filter(item=>contexts.value.some(ctx=>ctx.module===item.id))),moduleContexts=computed(()=>contexts.value.filter(item=>item.module===context.value?.module)),tools=computed(()=>overview.value?.tools||[]),benefit=computed(()=>overview.value?.benefits.find(item=>item.id===tierId.value)),relation=computed(()=>overview.value?.[relationOpen.value]||{}),relationTitle=computed(()=>relationOpen.value==='superior'?'区域上级':'推荐人')
async function load(){const current=++epoch;status.value='loading';error.value='';moduleOpen.value=false;contextOpen.value=false;relationOpen.value='';wholesaleOverlay.value='';try{const rows=await getBusinessContexts();const selected=await getBusinessContext(contextId?null:props.initialModule||null,contextId||undefined);const result=await getBusinessOverview(selected.module,selected.id);if(current!==epoch)return;contextId=selected.id;contexts.value=rows;overview.value=result;tierId.value=result.benefits.some(item=>item.id===tierId.value)?tierId.value:result.benefits[1]?.id||result.benefits[0]?.id||'';status.value='ready'}catch(reason){if(current===epoch){error.value=reason.message||'工作台加载失败';status.value=reason.code==='FORBIDDEN'?'forbidden':'error'}}}
async function switchContext(id){if(switching)return;switching=true;moduleOpen.value=false;contextOpen.value=false;try{const selected=await selectBusinessContext(id);contextId=selected.id;await load()}catch(reason){uni.showToast({title:reason.message,icon:'none'})}finally{switching=false}}
function switchModule(module){const selected=contexts.value.find(item=>item.module===module);if(selected)switchContext(selected.id)}
function openTool(item){if(context.value.module==='wholesale' && ['superior','promotion','share'].includes(item.id)){wholesaleOverlay.value=item.id;return}uni.navigateTo({url:`${item.path}?contextId=${encodeURIComponent(context.value.id)}`})}
function openId(id){const item=tools.value.find(item=>item.id===id);if(item)openTool(item);else uni.showToast({title:'当前身份无此功能权限',icon:'none'})}
function copyInvite(){if(overview.value?.inviteCode)uni.setClipboardData({data:overview.value.inviteCode,fail:()=>uni.showToast({title:'复制失败，请重试',icon:'none'})})}
function showRelation(kind){relationOpen.value=kind}
onMounted(load);onUnmounted(()=>{++epoch});defineExpose({refresh:load})
</script>
<style>@import '../styles/account.css';@import '../styles/exclusive.css';@import '../styles/business.css';</style>

<style scoped>
