0 0;min-height:calc(100vh - 29em);background:linear-gradient(#28345c,#22274d)}.wholesale-dashboard .business-section-title{font-size:1em;margin-bottom:1.1em;background:linear-gradient(135deg,#dbdaff,#fffcef,#c0e3f0);background-clip:text;color:transparent}.benefits-spark{font-size:.8em;padding:0 .5em}.wholesale-dashboard .business-benefit-tabs{gap:.6em;flex-wrap:nowrap}.wholesale-dashboard .business-benefit-tabs button{padding:.15em;font-size:.85em;line-height:1.8}.wholesale-dashboard :deep(.empty-state){padding:2.5em 0 3em}.wholesale-dashboard :deep(.empty-state image){width:8em;height:8em}.rank-experience{margin:1.7em 0 .3em;height:.3em;border-radius:1em;background:#444e73;overflow:hidden}.rank-experience>view{height:100%;background:linear-gradient(90deg,#00b7ff,#3157ff)}.wholesale-dashboard .business-dialog-title{justify-content:center;font-size:1.1em}.wholesale-dashboard .business-dialog-title button{position:absolute;right:1em;top:1em}.wholesale-dashboard .business-dialog{position:relative;padding:1.5em 1em}.wholesale-dashboard .business-module-options image{width:2.5em;height:2.5em}.wholesale-dashboard .business-module-options button{font-size:.85em}.wholesale-dashboard .business-module-options .business-muted{display:none}
