.business-page:not(.wholesale-dashboard) .business-stats button{background:linear-gradient(180deg,#4e6da5 0%,#304978 45%,#192542 100%);box-shadow:inset 0 1rpx rgba(222,240,255,.28),0 8rpx 18rpx rgba(6,13,36,.16)}.business-page:not(.wholesale-dashboard) .business-relations button{border-radius:.85em;border:1rpx solid rgba(109,160,223,.36);background:linear-gradient(180deg,#4b6798 0%,#324975 48%,#1e2b49 100%);box-shadow:inset 0 1rpx rgba(220,239,255,.22)}.business-relation-mask{align-items:center}.business-relation-dialog{position:relative;width:min(88vw,25em);padding:2.5em 1.6em 1.5em;border-radius:1.3em;border:1rpx solid rgba(141,193,255,.58);background:radial-gradient(ellipse at 50% 0,rgba(105,181,255,.28),transparent 52%),linear-gradient(155deg,#405f96 0%,#303d64 48%,#252d4d 100%);box-shadow:0 1.5em 4em rgba(0,0,0,.52),inset 0 1rpx rgba(234,246,255,.38)}.business-relation-close{position:absolute;right:.8em;top:.55em;margin:0;padding:.1em .4em;background:none;color:#d9eaff;font-size:1.7em;line-height:1}.business-relation-title{text-align:center;font-size:1.2em;font-weight:700;letter-spacing:.1em}.business-relation-profile{display:flex;align-items:center;gap:.9em;min-height:5.5em;margin:1.6em 0 .9em;padding:1em;border-radius:.8em;border:1rpx solid rgba(148,197,255,.23);background:linear-gradient(180deg,rgba(106,141,192,.75),rgba(48,60,96,.95));box-shadow:inset 0 1rpx rgba(240,248,255,.2)}.business-relation-avatar{width:3.2em;height:3.2em;display:flex;align-items:center;justify-content:center;flex-shrink:0;border-radius:50%;background:linear-gradient(145deg,#a3dcff,#3d62ac);color:#162851;font-size:1.25em;font-weight:700}.business-relation-profile>view:last-child{min-width:0;font-size:1.1em;font-weight:600;overflow-wrap:anywhere}.business-relation-profile text,.business-relation-note{display:block;color:#adc0dc;font-size:.82em;font-weight:400;line-height:1.7}.business-relation-note{padding-top:.8em;border-top:1rpx solid rgba(180,210,246,.2);text-align:center}
